\mathsf{Ax}_{Line}^{EH}=\left\{\forall a,b:\mathsf{Pt}
(a\ne_{\mathsf{Pt}}b\to\exists l:\mathsf{Ln}(a\in l\wedge b\in l
\wedge\forall m:\mathsf{Ln}((a\in m\wedge b\in m)\to m\doteq_{\mathsf{Ln}}l)))\right\}

\begin{aligned}
\mathsf{Ax}_{Ord}^{EH}={}&
\{\forall a,b,c:\mathsf{Pt}(B(a,b,c)\to B(c,b,a))\}\\
&\cup\{\forall a,b,c:\mathsf{Pt}(B(a,b,c)\to
(a\ne_{\mathsf{Pt}}b\wedge b\ne_{\mathsf{Pt}}c\wedge a\ne_{\mathsf{Pt}}c\wedge Col(a,b,c)))\}\\
&\cup\{\forall a,b:\mathsf{Pt}(a\ne_{\mathsf{Pt}}b\to\exists c:\mathsf{Pt}\,B(a,b,c))\}\\
&\cup\{\forall a,b,c,p,q:\mathsf{Pt}
((\neg Col(a,b,c)\wedge B(a,p,c)\wedge B(b,q,c))
\to\exists x:\mathsf{Pt}(B(p,x,b)\wedge B(q,x,a)))\}.
\end{aligned}

\begin{aligned}
\mathsf{Ax}_{Circle}^{EH}={}&
\{\forall o,a,b:\mathsf{Pt}(a\ne_{\mathsf{Pt}}b\to
\exists c:\mathsf{Circ}(Ctr(o,c)\wedge Rad(c,a,b)\\
&\hspace{31mm}\wedge\forall d:\mathsf{Circ}((Ctr(o,d)\wedge Rad(d,a,b))
\to d\doteq_{\mathsf{Circ}}c)))\}\\
&\cup\{\forall o,a,b,p:\mathsf{Pt}\forall c:\mathsf{Circ}
((Ctr(o,c)\wedge Rad(c,a,b))\to(p\in c\leftrightarrow E(o,p,a,b)))\}\\
&\cup\{\forall o,a,b:\mathsf{Pt}\forall c:\mathsf{Circ}
((Ctr(o,c)\wedge Rad(c,a,b))\to\exists p:\mathsf{Pt}\,p\in c)\}.
\end{aligned}

\mathsf{Ax}_{Construct}^{EH}=
\{\forall l:\mathsf{Ln}\forall c:\mathsf{Circ}\forall p,q:\mathsf{Pt}
((p\in l\wedge q\in l\wedge Inside(p,c)\wedge Outside(q,c))
\to\exists r:\mathsf{Pt}\,MeetLC(l,c,r))\}

\cup\{\forall c,d:\mathsf{Circ}\forall p,q:\mathsf{Pt}
((p\in c\wedge q\in c\wedge Inside(p,d)\wedge Outside(q,d))
\to\exists r:\mathsf{Pt}\,MeetCC(c,d,r))\}.

\mathsf{Ax}_{Euclid}^{EH}=\{\forall l:\mathsf{Ln}\forall p:\mathsf{Pt}
(\neg(p\in l)\to\exists m:\mathsf{Ln}(p\in m\wedge Par(l,m)
\wedge\forall n:\mathsf{Ln}((p\in n\wedge Par(l,n))\to n\doteq_{\mathsf{Ln}}m)))\}.
